begin;
create extension if not exists pgtap with schema extensions;
select plan(9);
insert into public.b2c_classes(id,program_slug,name,capacity) values('16300000-0000-4000-8000-000000000001','tieng-anh','TEST-ZALO',10),('16300000-0000-4000-8000-000000000002','tieng-anh','TEST-ZALO-OTHER',10);
select set_config('request.jwt.claims',json_build_object('sub',(select id from public.profiles where role='super_admin' and is_active limit 1),'role','authenticated')::text,true);
set local role authenticated;
select set_config('test.zalo_payload','{"request_id":"16300000-0000-4000-8000-000000000010","class_id":"16300000-0000-4000-8000-000000000001","mode":"new","full_name":"TEST-ZALO-NEW","phone":"0901111222","salesperson":"TEST-SALES","enrollment_date":"2026-10-16"}',true);
select lives_ok($$select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb)$$,'Zalo may be omitted');
select ok((select guardian_zalo is null from public.b2c_students where source_key='manual:16300000-0000-4000-8000-000000000010'),'Missing Zalo stays null, not inferred from phone');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb||'{"request_id":"16300000-0000-4000-8000-000000000011","guardian_zalo":" 0912345678 "}')$$,'Zalo stored with no guardian name requirement');
select is((select guardian_zalo from public.b2c_students where source_key='manual:16300000-0000-4000-8000-000000000011'),'0912345678','Zalo is trimmed and independent of contact phone');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb||'{"request_id":"16300000-0000-4000-8000-000000000012","guardian_zalo":"   "}')$$,'Blank Zalo accepted');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb||'{"request_id":"16300000-0000-4000-8000-000000000013","guardian_zalo":"123abc"}')$$,'22023',null,'Invalid Zalo rejected server-side');
select is((select count(*)::integer from public.b2c_students where source_key='manual:16300000-0000-4000-8000-000000000013'),0,'Invalid Zalo creates no orphan');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb||'{"request_id":"16300000-0000-4000-8000-000000000011","guardian_zalo":" 0912345678 "}')$$,'Retry with Zalo does not duplicate');
select public.add_b2c_class_student(current_setting('test.zalo_payload')::jsonb||jsonb_build_object('request_id','16300000-0000-4000-8000-000000000014','class_id','16300000-0000-4000-8000-000000000002','mode','existing','student_id',(select id from public.b2c_students where source_key='manual:16300000-0000-4000-8000-000000000011'),'guardian_zalo','0999999999'));
select is((select guardian_zalo from public.b2c_students where source_key='manual:16300000-0000-4000-8000-000000000011'),'0912345678','Existing student enrollment does not overwrite shared Zalo');
select * from finish();
rollback;
